"""Generate the synthetic labeled denial set in ``denial_set.json``. No real patient or claim.

Implements: US-12.2 (the labeled de-identified eval set, design decision 1: synthetic cases
labeled by construction, each denied under a reason code ``REASON_GUIDE`` lists for its family),
US-12.3 (the latency benchmark: the documents rotate through 835 text, a denial letter, and an EOB
PDF). Rules: NFR-1, NFR-3, BR-14 (patients are ``SYNTHETIC``; payers, clinics, and claim numbers
are invented).

The generator is seeded so the committed JSON is reproducible
(``test_us_12_2_denial_set_is_reproducible``)::

    uv run python -m tests.fixtures.denials.generate
"""

from __future__ import annotations

import json
import random
from pathlib import Path
from typing import Final

from claimcoach.cases.diagnosis import DenialReason
from claimcoach.evals.datasets import DenialEvalSet

__all__ = ["FIXTURE_PATH", "generate", "main"]

FIXTURE_PATH: Final = Path(__file__).with_name("denial_set.json")
SEED: Final = 1212
PER_REASON: Final = 2
NAME: Final = "synthetic-denials-v1"
PROVENANCE: Final = (
    "Synthetic cases generated by tests/fixtures/denials/generate.py (seed 1212), labeled by "
    "construction: each is denied under a reason code that REASON_GUIDE lists for its label. "
    "No real patient, claim, or payer. Pending review by a billing manager before a release."
)

CODES: Final[dict[DenialReason, tuple[tuple[str, str], ...]]] = {
    DenialReason.ELIGIBILITY: (("CO", "27"), ("CO", "109")),
    DenialReason.PRIOR_AUTHORIZATION: (("CO", "197"), ("CO", "15")),
    DenialReason.MEDICAL_NECESSITY: (("CO", "50"), ("CO", "167")),
    DenialReason.CODING_ERROR: (("CO", "4"), ("CO", "11")),
    DenialReason.MISSING_INFORMATION: (("CO", "16"), ("CO", "252")),
    DenialReason.DUPLICATE_CLAIM: (("OA", "18"), ("CO", "18")),
    DenialReason.TIMELY_FILING: (("CO", "29"), ("CO", "29")),
    DenialReason.NON_COVERED_SERVICE: (("PR", "96"), ("CO", "204")),
    DenialReason.BUNDLING: (("CO", "97"), ("CO", "234")),
    DenialReason.COORDINATION_OF_BENEFITS: (("OA", "22"), ("OA", "23")),
}
"""Two group/reason-code pairs per family (OTHER has no code that signals it)."""

TITLES: Final = {
    "4": "The procedure code is inconsistent with the modifier used",
    "11": "The diagnosis is inconsistent with the procedure",
    "15": "The authorization number is missing, invalid, or does not apply",
    "16": "Claim/service lacks information needed for adjudication",
    "18": "Exact duplicate claim/service",
    "22": "This care may be covered by another payer per coordination of benefits",
    "23": "The impact of prior payer adjudication",
    "27": "Expenses incurred after coverage terminated",
    "29": "The time limit for filing has expired",
    "50": "These are non-covered services because this is not deemed a medical necessity",
    "96": "Non-covered charge(s)",
    "97": "The benefit for this service is included in another service already adjudicated",
    "109": "Claim/service not covered by this payer/contractor",
    "167": "This (these) diagnosis(es) is (are) not covered",
    "197": "Precertification/authorization/notification/pre-treatment absent",
    "204": "This service is not covered under the patient's current benefit plan",
    "234": "This procedure is not paid separately",
    "252": "An attachment/other documentation is required to adjudicate this claim",
}
PAYERS: Final = ("ACME HEALTH PLAN", "NORTHWIND MUTUAL", "BLUE HERON CARE", "SUMMIT PEAK HEALTH")
PROCEDURES: Final = ("99213", "99214", "97110", "71046", "80053", "93000")
KINDS: Final = ("era_835", "letter", "eob_pdf")


def _era(v: dict[str, str]) -> str:
    return (
        "ISA*00*          *00*          *ZZ*PAYERID        *ZZ*PROVIDERID     *261015*1200*^*00501*"
        "000000001*0*P*:~GS*HP*PAYERID*PROVIDERID*20261015*1200*1*X*005010X221A1~"
        "ST*835*0001~BPR*I*0*C*NON************20261015~TRN*1*12345*1512345678~"
        f"N1*PR*{v['payer']}~N1*PE*SYNTHETIC CLINIC*XX*1234567893~"
        f"CLP*PCN-{v['n']}*4*{v['billed']}*0**12*{v['claim']}*11*1~NM1*QC*1*PATIENT*SYNTHETIC~"
        f"SVC*HC:{v['cpt']}*{v['billed']}*0**1~DTM*472*{v['dos'].replace('-', '')}~"
        f"CAS*{v['group']}*{v['carc']}*{v['billed']}~"
        "SE*12*0001~GE*1*1~IEA*1*000000001~"
    )


def _letter(v: dict[str, str]) -> str:
    return (
        f"{v['payer'].title()} - Notice of Claim Denial\n"
        "October 15, 2026\n\n"
        "Synthetic Clinic\n\n"
        f"Re: Claim {v['claim']}, date of service {v['dos']}\n\n"
        "Dear Provider,\n"
        f"We reviewed claim {v['claim']} for procedure {v['cpt']} billed at ${v['billed']}.00 and "
        f"denied it with group code {v['group']} and reason code {v['carc']}: {v['title']}.\n"
        f"Amount paid: $0.00. Amount denied: ${v['billed']}.00.\n"
        "You may appeal this decision within the time limit in your provider agreement.\n\n"
        "Claims Department\n"
    )


def _eob(v: dict[str, str]) -> str:
    return (
        f"EXPLANATION OF BENEFITS - {v['payer'].title()}\n"
        "Patient: SYNTHETIC PATIENT    Provider: Synthetic Clinic\n"
        f"Claim {v['claim']}    Processed 2026-10-15\n"
        "Service date   Procedure   Billed     Paid    Group  Reason\n"
        f"{v['dos']}     {v['cpt']}       ${v['billed']}.00   $0.00   {v['group']}     "
        f"{v['carc']}\n"
        f"Reason {v['group']}-{v['carc']}: {v['title']}.\n"
    )


_RENDER: Final = {"era_835": _era, "letter": _letter, "eob_pdf": _eob}


def generate() -> DenialEvalSet:
    """Build the set: ``PER_REASON`` cases per labeled family, document kinds in rotation."""
    rng = random.Random(SEED)  # noqa: S311 - reproducible fixtures, not secrets
    cases: list[dict[str, object]] = []
    for reason, codes in CODES.items():
        for group, carc in codes[:PER_REASON]:
            n = len(cases) + 1
            values = {
                "n": f"{n:04d}",
                "payer": rng.choice(PAYERS),
                "claim": f"CLM-{rng.randint(100000, 999999)}",
                "cpt": rng.choice(PROCEDURES),
                "billed": str(rng.randrange(80, 900, 5)),
                "dos": f"2026-{rng.randint(6, 9):02d}-{rng.randint(1, 28):02d}",
                "group": group,
                "carc": carc,
                "title": TITLES[carc],
            }
            kind = KINDS[(n - 1) % len(KINDS)]
            cases.append(
                {
                    "id": f"denial_{n:03d}",
                    "denial_reason": reason.value,
                    "documents": [{"kind": kind, "text": _RENDER[kind](values)}],
                }
            )
    return DenialEvalSet.model_validate({"name": NAME, "provenance": PROVENANCE, "cases": cases})


def main() -> int:
    """Write ``denial_set.json``."""
    data = generate().model_dump(mode="json")
    FIXTURE_PATH.write_text(json.dumps(data, indent=2) + "\n", encoding="utf-8")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
